  for( var i = -np; i &lt;= np; i++) {
    var p = Smax*i/np
    var gp = g(p)
    points[idx++] = { x: -Smax, y: -Smax*p - gp, index: i }
    points[idx++] = { x:  Smax, y:  Smax*p - gp, index: i }
  }

  return points
}
